select cron.unschedule(jobid) from cron.job where jobname='powerhouse-blog-queue-daytime';
select cron.schedule('powerhouse-blog-queue-daytime','17,37,57 6-16 * * *', $$select net.http_post(url := 'https://adhjwmvyoixzjtmiroln.supabase.co/functions/v1/powerhouse-blog-queue', headers := jsonb_build_object('content-type','application/json','x-powerhouse-token',(select decrypted_secret from vault.decrypted_secrets where name='powerhouse_daily_scheduler_token' order by created_at desc limit 1)), body := jsonb_build_object('runDate',(now() at time zone 'Europe/Amsterdam')::date::text), timeout_milliseconds := 30000);$$);
